<?php require __DIR__.'/../bootstrap.php';if(current_user())redirect('/dashboard/');$msg='';$requestedPlan=(string)($_POST['plan']??($_GET['plan']??'free'));$freeMeta=policy_data()['plan_meta']['free']??[];if($requestedPlan!=='free'||empty($freeMeta['enabled'])){$requestedPlan='free';if(empty($freeMeta['enabled']))$msg='Registration is temporarily unavailable because the Free plan is disabled.';}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($msg===''){if(!valid_email((string)post('email'))||strlen((string)post('password'))<10||post('password')!==post('confirm'))$msg='Enter a valid email and matching password of at least 10 characters.';else{try{$s=db()->prepare("INSERT INTO users(full_name,email,username,password_hash,role,plan,status,created_at,updated_at) VALUES(?,?,?,?, 'user',?,'active',NOW(),NOW())");$s->execute([post('name'),post('email'),post('username'),password_hash((string)post('password'),PASSWORD_DEFAULT),$requestedPlan]);login_user(['id'=>db()->lastInsertId()]);redirect('/dashboard/');}catch(Throwable $e){$msg='Email or username is already in use.';}}}}public_header('Sign Up');?><section class="center-card"><span class="eyebrow">Get started</span><h1>Create your workspace</h1><p class="sub">Start with tasks, notes and projects. AI remains optional.</p><?php if($msg):?><div class="flash error"><?=e($msg)?></div><?php endif;?><form method="post"><?=csrf_field()?> <input type="hidden" name="plan" value="<?=e($requestedPlan)?>"><label>Full Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Username<input name="username" required></label><label>Password<input type="password" name="password" minlength="10" required></label><label>Confirm Password<input type="password" name="confirm" minlength="10" required></label><button class="btn full">Create Account</button></form></section><?php public_footer(); ?>